#!/usr/bin/env node
/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename (in ascending lexicographic order) that it would apply.
 *
 * Naming convention expected for migration files:
 *   <version>_<description>.sql   e.g. 001_create_users.sql
 *
 * The lexicographic sort works correctly as long as the numeric prefix is
 * zero-padded to the same width across all files (001, 002, … 010, 011 …).
 *
 * Usage:
 *   node migrate.js                 # default: ./migrations
 *   node migrate.js ./other/path    # custom migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Directory that contains the *.sql migration files. */
const MIGRATIONS_DIR = path.resolve(process.argv[2] ?? './migrations');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Returns true when a directory entry is a regular file whose name ends with
 * '.sql' (case-insensitive).
 *
 * @param {fs.Dirent} dirent
 * @returns {boolean}
 */
function isSqlFile(dirent) {
  return dirent.isFile() && dirent.name.toLowerCase().endsWith('.sql');
}

/**
 * Compares two filenames so they sort in ascending lexicographic order.
 * When files are prefixed with a zero-padded integer (001_, 002_, …) this
 * produces the correct migration order.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function byFilename(a, b) {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

// ---------------------------------------------------------------------------
// Core logic
// ---------------------------------------------------------------------------

/**
 * Reads the migrations directory, filters for *.sql files, sorts them, then
 * logs each filename as it would be applied.
 *
 * @param {string} migrationsDir - Absolute path to the migrations directory.
 */
function runMigrations(migrationsDir) {
  // ── 1. Verify the directory exists ───────────────────────────────────────
  if (!fs.existsSync(migrationsDir)) {
    console.error(`[migrate] ERROR: Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // ── 2. Read directory entries ─────────────────────────────────────────────
  let entries;
  try {
    entries = fs.readdirSync(migrationsDir, { withFileTypes: true });
  } catch (err) {
    console.error(`[migrate] ERROR: Could not read directory: ${err.message}`);
    process.exit(1);
  }

  // ── 3. Filter + sort ──────────────────────────────────────────────────────
  const sqlFiles = entries
    .filter(isSqlFile)
    .map((dirent) => dirent.name)
    .sort(byFilename);

  // ── 4. Guard: nothing to do ───────────────────────────────────────────────
  if (sqlFiles.length === 0) {
    console.log('[migrate] No SQL migration files found. Nothing to apply.');
    return;
  }

  // ── 5. Log each file that would be applied ────────────────────────────────
  console.log(`[migrate] Found ${sqlFiles.length} migration(s) in: ${migrationsDir}`);
  console.log('[migrate] Applying migrations in the following order:\n');

  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);
    console.log(`  [${index + 1}/${sqlFiles.length}] ${filename}`);
    console.log(`         → ${filePath}`);
  });

  console.log('\n[migrate] Done — all migrations listed successfully.');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

runMigrations(MIGRATIONS_DIR);

