// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Directory that contains the *.sql migration files. */
const MIGRATIONS_DIR = path.resolve(process.argv[2] ?? './migrations');

/** Path to the .env file that provides DATABASE_URL. */
const ENV_FILE = path.resolve(process.env.ENV_FILE ?? '.env.test');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a minimal .env file (KEY=value lines) and returns a plain object.
 * Handles:
 *  - Lines beginning with # (comments) → ignored
 *  - Blank lines                        → ignored
 *  - Inline comments after the value    → stripped
 *  - Values wrapped in single or double quotes → unquoted
 *
 * This intentionally avoids `require('dotenv')` so the script stays
 * dependency-free.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                          // no '=' → skip

    const key = trimmed.slice(0, eqIdx).trim();
    let value  = trimmed.slice(eqIdx + 1).trim();

    // Strip inline comment  (space + # …)
    value = value.replace(/\s+#.*$/, '');

    // Strip surrounding quotes (single or double, must match)
    if (
      (value.startsWith('"')  && value.endsWith('"'))  ||
      (value.startsWith("'")  && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }

  return vars;
}

/**
 * Loads DATABASE_URL from the given .env file, validates it is present and
 * non-empty, then logs a sanitised "connected" line that shows the protocol,
 * host, port, and database name — but NEVER the username or password.
 *
 * @param {string} envFile - Absolute path to the .env file.
 * @returns {string} The raw DATABASE_URL value (for downstream use).
 */
function resolveAndLogConnection(envFile) {
  // ── 1. Confirm the env file exists ───────────────────────────────────────
  if (!fs.existsSync(envFile)) {
    console.error(`[migrate] ERROR: Env file not found: ${envFile}`);
    process.exit(1);
  }

  // ── 2. Parse and extract DATABASE_URL ────────────────────────────────────
  let envVars;
  try {
    envVars = parseEnvFile(envFile);
  } catch (err) {
    console.error(`[migrate] ERROR: Could not read env file: ${err.message}`);
    process.exit(1);
  }

  const databaseUrl = envVars['DATABASE_URL'];

  if (!databaseUrl) {
    console.error(`[migrate] ERROR: DATABASE_URL is not defined in ${envFile}`);
    process.exit(1);
  }

  // ── 3. Parse the URL to extract safe-to-log fields ───────────────────────
  let parsed;
  try {
    parsed = new URL(databaseUrl);
  } catch {
    console.error('[migrate] ERROR: DATABASE_URL is not a valid URL.');
    process.exit(1);
  }

  // Build a display string that deliberately omits credentials.
  // parsed.pathname is "/<dbname>"; strip the leading "/".
  const displayUrl = `${parsed.protocol}//${parsed.host}${parsed.pathname}`;

  // ── 4. Log the sanitised connection confirmation ──────────────────────────
  console.log(`[migrate] Env file     : ${envFile}`);
  console.log(`[migrate] Target       : ${displayUrl}`);
  console.log(`[migrate] Connected successfully (simulated).\n`);

  return databaseUrl;
}

