#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename it would apply, in ascending (lexicographic) order.
 *
 * Naming convention for migration files:
 *   <three-digit-number>_<description>.sql
 *   e.g. 001_create_users_table.sql
 *
 * Usage:
 *   node migrate.js
 */

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, "migrations");
const SQL_EXTENSION  = ".sql";

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns true when a filename looks like a valid, numbered migration file.
 * Valid pattern: one-or-more digits, an underscore, a description, ".sql"
 * Examples that pass : 001_create_users_table.sql  |  042_drop_legacy_index.sql
 * Examples that fail : .DS_Store  |  README.md  |  _no_number.sql
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isMigrationFile(filename) {
  return /^\d+_.+\.sql$/i.test(filename);
}

/**
 * Reads all valid migration filenames from `dir`, sorted in ascending
 * lexicographic order (which matches numeric order when files are
 * zero-padded, e.g. 001, 002, …, 099, 100).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of migration filenames (not full paths).
 * @throws {Error}     If the directory cannot be read.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  const migrationFiles = entries
    .filter((entry) => {
      // Only keep regular files with the right naming pattern.
      const fullPath = path.join(dir, entry);
      const isFile   = fs.statSync(fullPath).isFile();
      return isFile && isMigrationFile(entry);
    })
    .sort(); // Lexicographic sort — relies on zero-padded numeric prefix.

  return migrationFiles;
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point.  Discovers migration files and logs the order in which they
 * would be applied.  Replace the log statements inside the loop with your
 * real database execution logic when you wire this up to an actual DB client.
 */
function main() {
  console.log("=".repeat(60));
  console.log(" Database Migration Runner");
  console.log("=".repeat(60));
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log("-".repeat(60));

  // ── Discover files ──────────────────────────────────────────────────────────
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log("No migration files found. Nothing to apply.");
    console.log("=".repeat(60));
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);

  // ── Log each migration in order ─────────────────────────────────────────────
  files.forEach((filename, index) => {
    const step     = String(index + 1).padStart(2, "0");   // "01", "02", …
    const fullPath = path.join(MIGRATIONS_DIR, filename);

    console.log(`  [${step}] Applying : ${filename}`);
    console.log(`       Full path : ${fullPath}`);

    // ── TODO: replace the block below with real DB execution ──────────────────
    //
    //   const sql = fs.readFileSync(fullPath, "utf8");
    //   await db.query(sql);
    //
    // ─────────────────────────────────────────────────────────────────────────
  });

  console.log("\n" + "-".repeat(60));
  console.log(`[DONE] ${files.length} migration(s) listed successfully.`);
  console.log("=".repeat(60));
}

main();

