#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads DATABASE_URL from .env.test, simulates a connection, then reads all
 * *.sql files from the ./migrations/ directory and logs each filename it
 * would apply, in ascending (lexicographic) order.
 *
 * Naming convention for migration files:
 *   <three-digit-number>_<description>.sql
 *   e.g. 001_create_users_table.sql
 *
 * Usage:
 *   node migrate.js
 */

const fs   = require("fs");
const path = require("path");

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, "migrations");
const ENV_FILE       = path.resolve(__dirname, ".env.test");

// ─── .env Parser ─────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 *
 * Supported syntax:
 *   - KEY=value            plain value
 *   - KEY="value"          double-quoted value (quotes stripped)
 *   - KEY='value'          single-quoted value (quotes stripped)
 *   - # comment            ignored
 *   - blank lines          ignored
 *
 * Leading/trailing whitespace around both the key and the value is trimmed.
 * The parser intentionally avoids third-party dependencies (e.g. dotenv) so
 * the script stays self-contained.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw new Error(`Failed to read env file: ${err.message}`);
  }

  const result = {};

  raw.split("\n").forEach((line, lineNumber) => {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (trimmed === "" || trimmed.startsWith("#")) return;

    const separatorIndex = trimmed.indexOf("=");
    if (separatorIndex === -1) {
      // Not a key=value line — skip silently (could warn here if desired).
      return;
    }

    const key   = trimmed.slice(0, separatorIndex).trim();
    let   value = trimmed.slice(separatorIndex + 1).trim();

    if (!key) return; // Guard against lines like "=value".

    // Strip matching surrounding quotes, e.g. "foo" → foo, 'bar' → bar.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    result[key] = value;
  });

  return result;
}

/**
 * Resolves DATABASE_URL from the env file at `envPath`.
 * Validates that the value is present and looks like a connection string.
 *
 * @param {string} envPath - Absolute path to the .env file.
 * @returns {string} The validated connection string.
 * @throws {Error} If the variable is absent or malformed.
 */
function resolveConnectionString(envPath) {
  const env = parseEnvFile(envPath);

  const url = env["DATABASE_URL"];
  if (!url) {
    throw new Error(`DATABASE_URL is not set in ${envPath}`);
  }

  // Validate that the value is a recognisable database connection string.
  // Accepted schemes: postgres://, postgresql://, mysql://, sqlite://
  const SUPPORTED_SCHEMES = /^(postgres(?:ql)?|mysql|sqlite):\/\//i;
  if (!SUPPORTED_SCHEMES.test(url)) {
    throw new Error(
      `DATABASE_URL in ${envPath} is not a valid connection string.\n` +
      `  Accepted schemes : postgres://, postgresql://, mysql://, sqlite://\n` +
      `  Received         : ${url}`
    );
  }

  return url;
}

/**
 * Parses a connection string into its human-readable components and returns
 * a redacted version safe to print to a console or log file.
 *
 * Input : postgres://migrate_user:secret@localhost:5432/app_test
 * Output: { scheme, user, host, port, database, redacted }
 *         where redacted = "postgres://migrate_user:****@localhost:5432/app_test"
 *
 * @param {string} url
 * @returns {{ scheme: string, user: string, host: string, port: string,
 *             database: string, redacted: string }}
 */
function parseConnectionString(url) {
  // Use the built-in URL class — it handles all the edge cases for us.
  const parsed = new URL(url);

  const scheme   = parsed.protocol.replace(/:$/, ""); // strip trailing ":"
  const user     = parsed.username || "(none)";
  const host     = parsed.hostname;
  const port     = parsed.port     || defaultPortFor(scheme);
  const database = (parsed.pathname || "/").replace(/^\//, "") || "(default)";

  // Build a redacted URL: replace the password (if any) with "****".
  const redacted = parsed.password
    ? url.replace(`:${parsed.password}@`, ":****@")
    : url;

  return { scheme, user, host, port, database, redacted };
}

/**
 * Returns the conventional default port for a given DB scheme.
 *
 * @param {string} scheme - e.g. "postgres", "mysql"
 * @returns {string}
 */
function defaultPortFor(scheme) {
  const defaults = { postgres: "5432", postgresql: "5432", mysql: "3306", sqlite: "N/A" };
  return defaults[scheme.toLowerCase()] ?? "(unknown)";
}

// ─── Migration file helpers ───────────────────────────────────────────────────

/**
 * Returns true when a filename looks like a valid, numbered migration file.
 * Valid pattern: one-or-more digits, an underscore, a description, ".sql"
 * Examples that pass : 001_create_users_table.sql  |  042_drop_legacy_index.sql
 * Examples that fail : .DS_Store  |  README.md  |  _no_number.sql
 *
 * @param {string} filename
 * @returns {boolean}
 */
function isMigrationFile(filename) {
  return /^\d+_.+\.sql$/i.test(filename);
}

/**
 * Reads all valid migration filenames from `dir`, sorted in ascending
 * lexicographic order (which matches numeric order when files are
 * zero-padded, e.g. 001, 002, …, 099, 100).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of migration filenames (not full paths).
 * @throws {Error} If the directory cannot be read.
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === "ENOENT") {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw new Error(`Failed to read migrations directory: ${err.message}`);
  }

  return entries
    .filter((entry) => {
      const fullPath = path.join(dir, entry);
      return fs.statSync(fullPath).isFile() && isMigrationFile(entry);
    })
    .sort(); // Lexicographic sort — relies on zero-padded numeric prefix.
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log("=".repeat(60));
  console.log(" Database Migration Runner");
  console.log("=".repeat(60));

  // ── Step 1: resolve DATABASE_URL from .env.test ─────────────────────────────
  console.log(`\n[1/3] Reading connection string`);
  console.log(`      Env file : ${ENV_FILE}`);

  let connectionString;
  try {
    connectionString = resolveConnectionString(ENV_FILE);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  const { scheme, user, host, port, database, redacted } =
    parseConnectionString(connectionString);

  console.log(`      Found DATABASE_URL`);
  console.log(`        Scheme   : ${scheme}`);
  console.log(`        User     : ${user}`);
  console.log(`        Host     : ${host}`);
  console.log(`        Port     : ${port}`);
  console.log(`        Database : ${database}`);
  console.log(`        URL      : ${redacted}`);

  // ── Step 2: simulate connection ─────────────────────────────────────────────
  console.log(`\n[2/3] Connecting to database`);
  console.log(`      Successfully connected to ${scheme}://${host}:${port}/${database}`);

  // ── Step 3: discover and log migration files ────────────────────────────────
  console.log(`\n[3/3] Discovering migrations`);
  console.log(`      Directory : ${MIGRATIONS_DIR}`);

  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`\n[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log("      No migration files found. Nothing to apply.");
    console.log("\n" + "=".repeat(60));
    return;
  }

  console.log(`      Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const step     = String(index + 1).padStart(2, "0");
    const fullPath = path.join(MIGRATIONS_DIR, filename);

    console.log(`  [${step}] Applying : ${filename}`);
    console.log(`       Full path : ${fullPath}`);

    // ── TODO: replace the block below with real DB execution ──────────────────
    //
    //   const sql = fs.readFileSync(fullPath, "utf8");
    //   await db.query(sql);
    //
    // ─────────────────────────────────────────────────────────────────────────
  });

  console.log("\n" + "-".repeat(60));
  console.log(`[DONE] ${files.length} migration(s) listed successfully.`);
  console.log("=".repeat(60));
}

main();

