-- Migration 003: Add role column to users
ALTER TABLE users
  ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'member';

/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in the order it would be applied (lexicographic / numeric prefix).
 *
 * Usage:
 *   node migrate.js              # dry-run: just log filenames
 *   node migrate.js --verbose    # also print each file's SQL content
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const VERBOSE        = process.argv.includes('--verbose');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted lexicographically so that numeric prefixes (001_, 002_, …) produce
 * a deterministic application order.
 *
 * @param {string} dir - Directory to scan.
 * @returns {string[]} Sorted list of absolute file paths.
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort();                       // lexicographic sort: '001_...' < '002_...'

  if (sqlFiles.length === 0) {
    throw new Error(`No *.sql files found in: ${dir}`);
  }

  return sqlFiles.map(name => path.join(dir, name));
}

/**
 * Logs a formatted banner so output is easy to read in a terminal.
 *
 * @param {string} message
 */
function banner(message) {
  const line = '─'.repeat(60);
  console.log(`\n${line}\n  ${message}\n${line}`);
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  banner('Database Migration Runner (dry-run)');

  // 1. Discover migration files.
  let filePaths;
  try {
    filePaths = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`  Migrations directory : ${MIGRATIONS_DIR}`);
  console.log(`  Files found          : ${filePaths.length}\n`);

  // 2. Log each file in application order.
  filePaths.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    const position = String(index + 1).padStart(2, '0');

    console.log(`  [${position}] ${filename}`);

    // Optional: print the SQL content for review.
    if (VERBOSE) {
      const sql = fs.readFileSync(filePath, 'utf8').trimEnd();
      const indented = sql
        .split('\n')
        .map(line => `        ${line}`)
        .join('\n');
      console.log(indented);
      console.log();
    }
  });

  banner(`${filePaths.length} migration(s) ready to apply — dry-run complete`);
}

main();

