 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {{ DATABASE_URL?: string }} Parsed subset of env vars.
 * @throws {Error} If the file cannot be read.
 */
function parseEnvForDatabaseUrl(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Only process DATABASE_URL; skip everything else
    if (!trimmed.startsWith('DATABASE_URL=')) continue;

    const eqIndex = trimmed.indexOf('=');
    let value = trimmed.slice(eqIndex + 1).trim();

    // Strip surrounding quotes if present
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    result.DATABASE_URL = value;
    break; // Found what we need — stop reading
  }

  return result;
}

/**
 * Parses a connection URL and returns a safe, redacted version where the
 * password (if any) is replaced with "****".  This ensures credentials are
 * never printed to logs or consoles.
 *
 * Input:  postgres://admin:s3cr3t@db.host:5432/mydb
 * Output: postgres://admin:****@db.host:5432/mydb
 *
 * @param {string} url - The raw DATABASE_URL value.
 * @returns {{ redactedUrl: string, host: string, port: string, dbName: string }}
 */
function parseConnectionUrl(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(`DATABASE_URL is not a valid URL: ${url}`);
  }

  const host     = parsed.hostname || '(unknown host)';
  const port     = parsed.port     || '(default port)';
  const dbName   = (parsed.pathname || '/').replace(/^\//, '') || '(default db)';

  // Build a redacted URL — replace the password but preserve everything else
  const redactedUrl = parsed.password
    ? url.replace(`:${parsed.password}@`, ':****@')
    : url;

  return { redactedUrl, host, port, dbName };
}

