  console.log(`Reading env file: ${ENV_FILE}`);

  let env;
  try {
    env = parseEnvForDatabaseUrl(ENV_FILE);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  const rawUrl = env.DATABASE_URL || process.env.DATABASE_URL;
  if (!rawUrl) {
    console.error(
      'Error: DATABASE_URL is not defined in the env file or environment.'
    );
    process.exit(1);
  }

  let connectionInfo;
  try {
    connectionInfo = parseConnectionUrl(rawUrl);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  const { redactedUrl, host, port, dbName } = connectionInfo;
  console.log(`  DATABASE_URL resolved: ${redactedUrl}`);
  console.log(
    `  → Simulating connection to host=${host}  port=${port}  db=${dbName}`
  );
  console.log('  ✔ Connected successfully (simulated)\n');

  // ── Step 2: Discover migration files ─────────────────────────────────────
  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No SQL migration files found. Nothing to apply.');
    return;
  }

  // ── Step 3: Log files in order ────────────────────────────────────────────
  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(
      `  [${String(index + 1).padStart(3, '0')}] ${filename}  (${sizeKB} KB)`
    );
  });

  console.log('\nDry run complete — no changes were made to the database.');
}

main();

