#!/usr/bin/env node

/**
 * migrate.js
 *
 * 1. Reads DATABASE_URL from .env.test and logs a (redacted) connection line.
 * 2. Reads every *.sql file from the ./migrations/ directory and logs the
 *    filename of each migration it would apply, in lexicographic (alphabetical)
 *    order.
 *
 * Lexicographic order works correctly with the zero-padded numeric prefix
 * convention used here (e.g. 001_, 002_, 003_ …).
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE       = path.resolve(__dirname, '.env.test');
const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parses a .env file into a plain key/value object.
 *
 * Handles:
 *   - Blank lines and lines starting with # (comments) — skipped.
 *   - Optional surrounding single or double quotes on values.
 *   - Inline comments after an unquoted value (e.g. KEY=value # note).
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  let raw;

  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const result = {};

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;                       // no '=' → malformed, skip

    const key = trimmed.slice(0, eqIndex).trim();
    let   val = trimmed.slice(eqIndex + 1);             // everything after the first '='

    // Strip an optional wrapping quote pair (' or ").
    const quoteMatch = val.match(/^(["'])([\s\S]*)\1$/);
    if (quoteMatch) {
      val = quoteMatch[2];
    } else {
      // Remove inline comment (e.g. value # note) for unquoted values.
      val = val.replace(/\s+#.*$/, '').trim();
    }

    if (key) result[key] = val;
  }

  return result;
}

/**
 * Resolves DATABASE_URL from the given env file.
 * Throws a descriptive error if the variable is absent or empty.
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {string} The raw DATABASE_URL value.
 */
function resolveDatabaseUrl(envFilePath) {
  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(
      `DATABASE_URL is not defined in ${envFilePath}. ` +
      'Add DATABASE_URL=<connection-string> and try again.'
    );
  }

  return env.DATABASE_URL;
}

/**
 * Returns a redacted version of a connection string that is safe to log.
 *
 * Any username and password embedded in the URL are replaced with asterisks
 * so that secrets never appear in console output, log files, or CI traces.
 *
 * Input  : postgres://admin:s3cr3t@db.host:5432/mydb
 * Output : postgres://***:***@db.host:5432/mydb
 *
 * If the URL cannot be parsed (e.g. it is not a standard connection string)
 * the function returns the fixed string '<unparseable URL>' rather than
 * leaking anything.
 *
 * @param {string} connectionString - Raw DATABASE_URL value.
 * @returns {string} Redacted connection string.
 */
function redactConnectionString(connectionString) {
  try {
    const url = new URL(connectionString);

    // Blank out credentials in-place on the parsed URL object.
    if (url.username) url.username = '***';
    if (url.password) url.password = '***';

    return url.toString();
  } catch {
    return '<unparseable URL>';
  }
}

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted in ascending lexicographic order by filename.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of absolute file paths.
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(filename => path.extname(filename).toLowerCase() === SQL_EXTENSION)
    .sort()                                   // lexicographic — relies on numeric prefix padding
    .map(filename => path.join(dir, filename));
}

/**
 * Reads a single SQL file and returns its contents as a string.
 *
 * @param {string} filePath - Absolute path to the SQL file.
 * @returns {string} The SQL source text.
 */
function readSqlFile(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  // ── Step 1: resolve & log the connection string ────────────────────────────
  const dbUrl   = resolveDatabaseUrl(ENV_FILE);
  const safeUrl = redactConnectionString(dbUrl);

  console.log(`Env file             : ${path.basename(ENV_FILE)}`);
  console.log(`Database URL         : ${safeUrl}`);
  console.log('✔  Connected to database successfully (simulated)\n');

  // ── Step 2: discover & log migration files ────────────────────────────────
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  if (sqlFiles.length === 0) {
    console.log('\nNo migration files found. Nothing to apply.');
    return;
  }

  console.log(`Migrations found     : ${sqlFiles.length}\n`);
  console.log('─'.repeat(50));

  sqlFiles.forEach((filePath, index) => {
    const filename  = path.basename(filePath);
    const sql       = readSqlFile(filePath);
    const lineCount = sql.split('\n').filter(line => line.trim() !== '').length;

    console.log(
      `[${String(index + 1).padStart(2, '0')}] Applying : ${filename}` +
      `  (${lineCount} non-blank line${lineCount !== 1 ? 's' : ''})`
    );

    // ── Placeholder for real execution ──────────────────────────────────────
    // In a real runner you would execute the SQL against your database here,
    // e.g.:  await client.query(sql);
    // and record the migration in a schema_migrations tracking table so that
    // already-applied files are skipped on subsequent runs.
    // ────────────────────────────────────────────────────────────────────────
  });

  console.log('─'.repeat(50));
  console.log(`\n✔  ${sqlFiles.length} migration${sqlFiles.length !== 1 ? 's' : ''} would be applied.`);
}

main();

