/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs each
 * filename in sorted order — the order they would be applied against the
 * database.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every *.sql file inside `dir`,
 * sorted lexicographically so that numeric prefixes (001_, 002_, …) produce
 * a deterministic, ascending application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of absolute file paths.
 * @throws {Error} If the directory cannot be read.
 */
function getSortedMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => name.endsWith('.sql'))   // only SQL files
    .sort()                                   // lexicographic / numeric-prefix order
    .map(name => path.join(dir, name));       // absolute paths
}

/**
 * Logs the filenames of the migrations that would be applied, in order.
 * Each line includes a 1-based index so the intended sequence is explicit.
 *
 * @param {string[]} filePaths - Sorted list of absolute migration file paths.
 */
function logMigrationPlan(filePaths) {
  if (filePaths.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${filePaths.length} migration file(s) in: ${MIGRATIONS_DIR}\n`);
  console.log('Migration plan (in application order):');
  console.log('────────────────────────────────────────');

  filePaths.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    console.log(`  [${String(index + 1).padStart(2, '0')}] ${filename}`);
  });

  console.log('────────────────────────────────────────');
  console.log('(dry run — no changes have been made)');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  try {
    const migrationFiles = getSortedMigrationFiles(MIGRATIONS_DIR);
    logMigrationPlan(migrationFiles);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
}

main();

