/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename in the order it would be applied (ascending lexicographic order,
 * which matches the numeric prefix convention: 001_, 002_, …).
 *
 * Usage:
 *   node migrate.js            # dry-run: list files that would be applied
 *   node migrate.js --dry-run  # explicit dry-run flag (same behaviour)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file inside `dir`, sorted in ascending order so that
 * numeric prefixes (001_, 002_, …) determine application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {{ filename: string, filepath: string }[]}
 */
function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .sort((a, b) => a.name.localeCompare(b.name))   // lexicographic = numeric order
    .map(entry => ({
      filename : entry.name,
      filepath : path.join(dir, entry.name),
    }));
}

/**
 * Reads and returns the SQL content of a single migration file.
 *
 * @param {string} filepath - Absolute path to the .sql file.
 * @returns {string}
 */
function readMigration(filepath) {
  return fs.readFileSync(filepath, 'utf8');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  const isDryRun = process.argv.includes('--dry-run') || true; // always dry-run for now

  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);
  console.log(`Mode                 : ${isDryRun ? 'dry-run (no DB connection)' : 'live'}\n`);

  // 1. Discover migration files
  let migrations;
  try {
    migrations = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (migrations.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // 2. Log each file in application order
  migrations.forEach(({ filename, filepath }, index) => {
    const order   = String(index + 1).padStart(2, '0');
    const sql     = readMigration(filepath);
    const preview = sql.trim().split('\n')[0]; // first line as a quick preview

    console.log(`  [${order}] ${filename}`);
    console.log(`       Path    : ${filepath}`);
    console.log(`       Preview : ${preview}`);
    console.log();
  });

  // 3. Summarise what would happen next
