/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * each filename in the order it would be applied (lexicographic /
 * numeric-prefix order, which matches the NNN_ naming convention).
 *
 * Usage:
 *   node migrate.js                 # dry-run: log filenames only
 *   node migrate.js --dir ./other   # override the migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/**
 * Parse a minimal set of CLI flags so the directory can be overridden
 * without touching the source file.
 *
 * Supported flags:
 *   --dir <path>   Directory that contains the *.sql migration files.
 *                  Defaults to ./migrations relative to this script.
 */
function parseArgs(argv) {
  const args = { dir: path.join(__dirname, 'migrations') };

  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--dir' && argv[i + 1]) {
      args.dir = path.resolve(argv[++i]);
    }
  }

  return args;
}

// ---------------------------------------------------------------------------
// Core logic
// ---------------------------------------------------------------------------

/**
 * Return every *.sql file inside `migrationsDir`, sorted lexicographically.
 * Lexicographic order works correctly when files are named with a zero-padded
 * numeric prefix (e.g. 001_, 002_, …).
 *
 * @param {string} migrationsDir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of full file paths.
 * @throws {Error} If the directory does not exist or cannot be read.
 */
function getSqlFiles(migrationsDir) {
  if (!fs.existsSync(migrationsDir)) {
    throw new Error(`Migrations directory not found: ${migrationsDir}`);
  }

  const stat = fs.statSync(migrationsDir);
  if (!stat.isDirectory()) {
    throw new Error(`Path is not a directory: ${migrationsDir}`);
  }

  const entries = fs.readdirSync(migrationsDir);

  const sqlFiles = entries
