// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/**
 * Parse a minimal set of CLI flags so the directory and env file can be
 * overridden without touching the source file.
 *
 * Supported flags:
 *   --dir <path>       Directory that contains the *.sql migration files.
 *                      Defaults to ./migrations relative to this script.
 *   --env-file <path>  .env file to load DATABASE_URL from.
 *                      Defaults to .env.test relative to this script.
 */
function parseArgs(argv) {
  const args = {
    dir:     path.join(__dirname, 'migrations'),
    envFile: path.join(__dirname, '.env.test'),
  };

  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === '--dir' && argv[i + 1]) {
      args.dir = path.resolve(argv[++i]);
    } else if (argv[i] === '--env-file' && argv[i + 1]) {
      args.envFile = path.resolve(argv[++i]);
    }
  }

  return args;
}

// ---------------------------------------------------------------------------
// .env parsing
// ---------------------------------------------------------------------------

/**
 * Parse a .env file into a plain key/value object.
 *
 * Handles the most common .env syntax without requiring third-party packages:
 *   - Blank lines and lines whose first non-space character is '#' are skipped.
 *   - Each line must be KEY=VALUE (extra whitespace around the '=' is trimmed).
 *   - Values wrapped in matching single or double quotes are unquoted; the
 *     quotes themselves are stripped and no further escape processing is done.
 *   - Inline comments (` # …`) are NOT stripped — they would break connection
 *     strings that legitimately contain a '#' character.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 * @throws {Error} If the file does not exist or cannot be read.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const raw    = fs.readFileSync(filePath, 'utf8');
  const result = {};

  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and full-line comments.
    if (line === '' || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;               // no '=' → not a key=value line

    const key   = line.slice(0, eqIndex).trim();
    let   value = line.slice(eqIndex + 1).trim();

    if (key === '') continue;                   // guard against malformed lines

    // Strip matching surrounding quotes (single or double).
    if (
      (value.startsWith('"')  && value.endsWith('"'))  ||
      (value.startsWith("'")  && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    result[key] = value;
  }

  return result;
}

/**
 * Resolve DATABASE_URL by checking (in priority order):
 *   1. The current process environment (process.env.DATABASE_URL).
 *   2. The supplied .env file.
 *
 * Giving the live environment higher priority is intentional: it allows CI
 * pipelines or Docker environments to inject the real URL without modifying
 * the file on disk.
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {{ url: string, source: string }} The resolved URL and its origin.
 * @throws {Error} If DATABASE_URL cannot be found in either location.
 */
function resolveDatabaseUrl(envFilePath) {
  // 1. Live environment variable wins.
  if (process.env.DATABASE_URL) {
    return { url: process.env.DATABASE_URL, source: 'process.env' };
  }

  // 2. Fall back to the .env file.
  const env = parseEnvFile(envFilePath);
  if (env.DATABASE_URL) {
    return { url: env.DATABASE_URL, source: path.basename(envFilePath) };
  }

  throw new Error(
    `DATABASE_URL is not defined in the environment or in ${envFilePath}`
  );
}

/**
 * Redact the password segment of a postgres:// (or any user:pass@host) URL
 * so it is safe to print in logs.
 *
 * Input:  postgres://admin:s3cr3t@db.host:5432/mydb
 * Output: postgres://admin:***@db.host:5432/mydb
 *
 * If the URL cannot be parsed (e.g. it uses an unexpected scheme or format),
 * the original string is returned unchanged — we never want a log line to
 * crash the runner.
 *
 * @param {string} rawUrl
 * @returns {string}
 */
function redactPassword(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.password) {
      parsed.password = '***';
    }
    return parsed.toString();
  } catch {
    // URL constructor failed — return as-is rather than crashing.
    return rawUrl;
  }
}

// ---------------------------------------------------------------------------
// Connection simulation
// ---------------------------------------------------------------------------

/**
 * Simulate establishing a database connection from a connection-string URL.
 * Parses the URL to extract the host, port, and database name so the log
 * message is meaningful; no real network I/O is performed.
 *
 * @param {string} url        - The raw DATABASE_URL connection string.
 * @param {string} source     - Human-readable label of where the URL came from.
 * @param {string} envFilePath - Absolute path to the env file (for display).
 */
function simulateConnection(url, source, envFilePath) {
  // Parse the URL to extract display-safe connection details.
  let host, port, database, user;
  try {
    const parsed = new URL(url);
    host     = parsed.hostname;
    port     = parsed.port || '5432';
    database = parsed.pathname.replace(/^\//, '') || '(default)';
    user     = parsed.username  || '(none)';
  } catch {
    throw new Error(`DATABASE_URL from ${source} is not a valid URL.`);
  }

  console.log('Database connection');
  console.log('─'.repeat(50));
  console.log(`  Env file    : ${envFilePath}`);
  console.log(`  URL source  : ${source}`);
  console.log(`  URL (safe)  : ${redactPassword(url)}`);
  console.log(`  Host        : ${host}`);
  console.log(`  Port        : ${port}`);
  console.log(`  Database    : ${database}`);
  console.log(`  User        : ${user}`);
  console.log('');
  console.log(`  ✔ Connected successfully to "${database}" on ${host}:${port}`);
  console.log('');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

(function main() {
  try {
    const { dir, envFile } = parseArgs(process.argv);

    // Step 1: Resolve and simulate the database connection.
    const { url, source } = resolveDatabaseUrl(envFile);
    simulateConnection(url, source, envFile);

    // Step 2: List the migrations that would be applied.
    logMigrations(dir);
  } catch (err) {
    console.error(`\nError: ${err.message}`);
    process.exit(1);
  }
})();

