);

/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs
 * the filenames in the order they would be applied.
 *
 * Ordering rules (applied in priority order):
 *   1. Files whose names begin with a numeric prefix (e.g. 001_, 002_)
 *      are sorted numerically by that prefix so that 2 always comes
 *      before 10, regardless of lexicographic order.
 *   2. Files with no numeric prefix follow after numbered files and
 *      are sorted alphabetically.
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir path/to/other/migrations
 */

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Resolve the migrations directory from an optional --dir CLI flag. */
function getMigrationsDir() {
  const dirFlagIndex = process.argv.indexOf('--dir');
  if (dirFlagIndex !== -1 && process.argv[dirFlagIndex + 1]) {
    return path.resolve(process.argv[dirFlagIndex + 1]);
  }
  return path.resolve(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Extract a leading integer prefix from a filename, if present.
 * e.g. "003_add_column.sql" → 3
 *      "add_column.sql"     → null
 */
function numericPrefix(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : null;
}

/**
 * Comparator that sorts migration filenames so that:
 *   - Numbered files come first, ordered by their numeric prefix.
 *   - Unnumbered files follow, ordered alphabetically.
 */
function migrationComparator(a, b) {
  const nA = numericPrefix(a);
  const nB = numericPrefix(b);

  if (nA !== null && nB !== null) return nA - nB;          // both numbered
  if (nA !== null)                return -1;                // only a is numbered → a first
  if (nB !== null)                return  1;                // only b is numbered → b first
  return a.localeCompare(b);                                // neither numbered → alphabetical
}

/**
 * Return a sorted list of *.sql filenames from the given directory.
 * Throws a descriptive error if the directory cannot be read.
 */
function getSqlFiles(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    if (err.code === 'ENOTDIR') {
      throw new Error(`Path is not a directory: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => name.toLowerCase().endsWith('.sql'))
    .sort(migrationComparator);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function main() {
  const migrationsDir = getMigrationsDir();

  console.log(`Migrations directory : ${migrationsDir}`);
  console.log('-------------------------------------------');

  let sqlFiles;
  try {
    sqlFiles = getSqlFiles(migrationsDir);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found. Nothing to apply.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s) — applying in this order:\n`);

  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);
    const stats    = fs.statSync(filePath);
    const sizeKB   = (stats.size / 1024).toFixed(2);

    console.log(`  [${String(index + 1).padStart(2, '0')}] ${filename}  (${sizeKB} KB)`);
  });

  console.log('\nDry run complete. No changes were made to the database.');
}

main();

