#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename in sorted (ascending) order — the order they would be applied
 * against the database.
 *
 * Usage:
 *   node migrate.js               # dry-run: log filenames only
 *   node migrate.js --dir <path>  # override the migrations directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

/** Parse optional --dir <path> CLI argument; fall back to ./migrations */
function getMigrationsDir() {
  const args = process.argv.slice(2);
  const dirFlagIndex = args.indexOf('--dir');

  if (dirFlagIndex !== -1) {
    const customDir = args[dirFlagIndex + 1];
    if (!customDir || customDir.startsWith('--')) {
      console.error('ERROR: --dir flag requires a path argument.');
      process.exit(1);
    }
    return path.resolve(customDir);
  }

  return path.resolve(__dirname, 'migrations');
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns all *.sql files inside `dir`, sorted lexicographically
 * (which keeps numeric prefixes like 001_, 002_ … in the correct order).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {{ filename: string, fullPath: string }[]}
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => name.endsWith('.sql'))
    .sort()                                          // lexicographic → correct numeric order
    .map(filename => ({ filename, fullPath: path.join(dir, filename) }));
}

/**
 * Validates that every entry in `files` is a readable regular file.
 * Exits with a non-zero code if any entry fails validation.
 *
 * @param {{ filename: string, fullPath: string }[]} files
 */
function validateFiles(files) {
  let hasError = false;

  for (const { filename, fullPath } of files) {
    try {
      const stat = fs.statSync(fullPath);
      if (!stat.isFile()) {
        console.error(`  SKIP  ${filename}  (not a regular file)`);
        hasError = true;
      }
    } catch (err) {
      console.error(`  ERROR ${filename}  (${err.message})`);
      hasError = true;
    }
  }

  if (hasError) {
    process.exit(1);
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  const migrationsDir = getMigrationsDir();

  console.log('='.repeat(60));
  console.log('  Database Migration Runner  (dry-run / logging mode)');
  console.log('='.repeat(60));
  console.log(`\nMigrations directory: ${migrationsDir}\n`);

  // 1. Discover migration files
  let files;
  try {
    files = getSqlFiles(migrationsDir);
  } catch (err) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No *.sql migration files found. Nothing to apply.');
    return;
  }

  // 2. Validate every file is readable
  validateFiles(files);

  // 3. Log each file in the order it would be applied
  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach(({ filename }, index) => {
    const step = String(index + 1).padStart(String(files.length).length, '0');
    console.log(`  [${step}/${files.length}]  ${filename}`);
  });

  console.log('\n' + '-'.repeat(60));
  console.log(`  ${files.length} migration(s) would be applied (dry-run complete).`);
  console.log('-'.repeat(60) + '\n');
}

main();

