// ─── Configuration ────────────────────────────────────────────────────────────

/**
 * Parses a named flag (e.g. --dir, --env) from process.argv.
 * Returns the value that follows the flag, or `null` if the flag is absent.
 * Exits with code 1 if the flag is present but has no value.
 *
 * @param {string} flag   - e.g. '--dir'
 * @param {string} label  - human-readable name used in error messages
 * @returns {string|null}
 */
function parseFlag(flag, label) {
  const args = process.argv.slice(2);
  const idx  = args.indexOf(flag);
  if (idx === -1) return null;

  const value = args[idx + 1];
  if (!value || value.startsWith('--')) {
    console.error(`ERROR: ${flag} flag requires a ${label} argument.`);
    process.exit(1);
  }
  return value;
}

/** Resolve the migrations directory from CLI args or the default. */
function getMigrationsDir() {
  const custom = parseFlag('--dir', 'path');
  return custom ? path.resolve(custom) : path.resolve(__dirname, 'migrations');
}

/** Resolve the .env file path from CLI args or the default. */
function getEnvFile() {
  const custom = parseFlag('--env', 'file path');
  return custom ? path.resolve(custom) : path.resolve(__dirname, '.env.test');
}

// ─── .env parsing & connection resolution ────────────────────────────────────

/**
 * Parses a .env-style file into a plain object.
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"
 *   - Lines starting with # (comments)
 *   - Blank lines
 *
 * The raw file contents are processed in memory and never logged.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`.env file not found: ${filePath}`);
    }
    throw err;
  }

  const vars = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;   // blank or comment

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                          // no '=' → skip

    const key = trimmed.slice(0, eqIdx).trim();
    let   val = trimmed.slice(eqIdx + 1).trim();

    // Strip optional surrounding quotes (" or ')
    if ((val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }

    vars[key] = val;
  }
  return vars;
}

/**
 * Extracts a sanitised connection descriptor from a postgres:// URL.
 * Returns ONLY the host and database name — the password and username
 * are deliberately omitted so they are never written to any log.
 *
 * Accepted format:
 *   postgres://user:password@host:port/dbname
 *   postgresql://user:password@host:port/dbname
 *
 * @param {string} raw - The full DATABASE_URL value.
 * @returns {{ host: string, db: string, displayString: string }}
 */
function parseDatabaseUrl(raw) {
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error(
      'DATABASE_URL is not a valid URL. ' +
      'Expected format: postgres://user:password@host:port/dbname'
    );
  }

  const validProtocols = ['postgres:', 'postgresql:'];
  if (!validProtocols.includes(parsed.protocol)) {
    throw new Error(
      `DATABASE_URL has unsupported protocol "${parsed.protocol}". ` +
      'Expected "postgres:" or "postgresql:".'
    );
  }

