#!/usr/bin/env node

/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename in sorted (ascending) order — the order they would be applied
 * against the database.
 *
 * Before listing migrations, the script resolves DATABASE_URL from a .env
 * file and logs a sanitised connection summary (host + db name only — the
 * password is never printed).
 *
 * Usage:
 *   node migrate.js                    # reads .env.test, migrations in ./migrations
 *   node migrate.js --dir <path>       # override the migrations directory
 *   node migrate.js --env <file>       # override the .env file (default: .env.test)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

/**
 * Parses a named flag (e.g. --dir, --env) from process.argv.
 * Returns the value that follows the flag, or `null` if the flag is absent.
 * Exits with code 1 if the flag is present but has no value.
 *
 * @param {string} flag   - e.g. '--dir'
 * @param {string} label  - human-readable name used in error messages
 * @returns {string|null}
 */
function parseFlag(flag, label) {
  const args = process.argv.slice(2);
  const idx  = args.indexOf(flag);
  if (idx === -1) return null;

  const value = args[idx + 1];
  if (!value || value.startsWith('--')) {
    console.error(`ERROR: ${flag} flag requires a ${label} argument.`);
    process.exit(1);
  }
  return value;
}

/** Resolve the migrations directory from CLI args or the default. */
function getMigrationsDir() {
  const custom = parseFlag('--dir', 'path');
  return custom ? path.resolve(custom) : path.resolve(__dirname, 'migrations');
}

/** Resolve the .env file path from CLI args or the default. */
function getEnvFile() {
  const custom = parseFlag('--env', 'file path');
  return custom ? path.resolve(custom) : path.resolve(__dirname, '.env.test');
}

// ─── .env parsing & connection resolution ────────────────────────────────────

/**
 * Parses a .env-style file into a plain object.
 * Handles:
 *   - KEY=value
 *   - KEY="quoted value"
 *   - Lines starting with # (comments)
 *   - Blank lines
 *
 * The raw file contents are processed in memory and never logged.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`.env file not found: ${filePath}`);
    }
    throw err;
  }

  const vars = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;   // blank or comment

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                          // no '=' → skip

    const key = trimmed.slice(0, eqIdx).trim();
    let   val = trimmed.slice(eqIdx + 1).trim();

    // Strip optional surrounding quotes (" or ')
    if ((val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }

    vars[key] = val;
  }
  return vars;
}

/**
 * Extracts a sanitised connection descriptor from a postgres:// URL.
 * Returns ONLY the host and database name — the password and username
 * are deliberately omitted so they are never written to any log.
 *
 * Accepted format:
 *   postgres://user:password@host:port/dbname
 *   postgresql://user:password@host:port/dbname
 *
 * @param {string} raw - The full DATABASE_URL value.
 * @returns {{ host: string, db: string, displayString: string }}
 */
function parseDatabaseUrl(raw) {
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error(
      'DATABASE_URL is not a valid URL. ' +
      'Expected format: postgres://user:password@host:port/dbname'
    );
  }

  const validProtocols = ['postgres:', 'postgresql:'];
  if (!validProtocols.includes(parsed.protocol)) {
    throw new Error(
      `DATABASE_URL has unsupported protocol "${parsed.protocol}". ` +
      'Expected "postgres:" or "postgresql:".'
    );
  }

  const host = parsed.hostname || '(unknown host)';
  const port = parsed.port     || '5432';            // postgres default
  const db   = (parsed.pathname || '/').replace(/^\//, '') || '(unknown db)';

  // Safe to log: host and db name are not secrets.
  // Port is structural metadata, also safe.
  const displayString = `${host}:${port}/${db}`;
  return { host, port, db, displayString };
}

/**
 * Resolves and validates DATABASE_URL from the given .env file, then
 * logs a sanitised connection summary.  The raw URL is never logged.
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 */
function resolveAndLogConnection(envFilePath) {
  console.log(`Reading environment from: ${path.basename(envFilePath)}`);

  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(`DATABASE_URL is not defined in ${path.basename(envFilePath)}.`);
  }

  // Parse — but log only the sanitised descriptor, never the raw URL.
  const { displayString } = parseDatabaseUrl(env.DATABASE_URL);

  console.log(`  Target database : ${displayString}`);
  console.log(`  Connection check: OK (simulated — no real connection made)\n`);
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns all *.sql files inside `dir`, sorted lexicographically
 * (which keeps numeric prefixes like 001_, 002_ … in the correct order).
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {{ filename: string, fullPath: string }[]}
 */
function getSqlFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => name.endsWith('.sql'))
    .sort()                                          // lexicographic → correct numeric order
    .map(filename => ({ filename, fullPath: path.join(dir, filename) }));
}

/**
 * Validates that every entry in `files` is a readable regular file.
 * Exits with a non-zero code if any entry fails validation.
 *
 * @param {{ filename: string, fullPath: string }[]} files
 */
function validateFiles(files) {
  let hasError = false;

  for (const { filename, fullPath } of files) {
    try {
      const stat = fs.statSync(fullPath);
      if (!stat.isFile()) {
        console.error(`  SKIP  ${filename}  (not a regular file)`);
        hasError = true;
      }
    } catch (err) {
      console.error(`  ERROR ${filename}  (${err.message})`);
      hasError = true;
    }
  }

  if (hasError) {
    process.exit(1);
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  const migrationsDir = getMigrationsDir();
  const envFilePath   = getEnvFile();

  console.log('='.repeat(60));
  console.log('  Database Migration Runner  (dry-run / logging mode)');
  console.log('='.repeat(60));
  console.log();

  // 1. Resolve DATABASE_URL and log a sanitised connection summary
  try {
    resolveAndLogConnection(envFilePath);
  } catch (err) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }

  console.log(`Migrations directory: ${migrationsDir}\n`);

  // 2. Discover migration files
  let files;
  try {
    files = getSqlFiles(migrationsDir);
  } catch (err) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No *.sql migration files found. Nothing to apply.');
    return;
  }

  // 3. Validate every file is readable
  validateFiles(files);

  // 4. Log each file in the order it would be applied
  console.log(`Found ${files.length} migration(s) to apply:\n`);

  files.forEach(({ filename }, index) => {
    const step = String(index + 1).padStart(String(files.length).length, '0');
    console.log(`  [${step}/${files.length}]  ${filename}`);
  });

  console.log('\n' + '-'.repeat(60));
  console.log(`  ${files.length} migration(s) would be applied (dry-run complete).`);
  console.log('-'.repeat(60) + '\n');
}

main();

