/**
 * migrate.js
 *
 * Reads all *.sql files from the ./migrations/ directory and logs each
 * filename (in ascending lexicographic order) that would be applied.
 *
 * Usage:
 *   node migrate.js
 *
 * Ordering convention:
 *   SQL files should be prefixed with a zero-padded sequence number so that
 *   lexicographic order matches the intended application order, e.g.:
 *     001_create_users.sql
 *     002_create_posts.sql
 *     003_add_users_role.sql
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an alphabetically sorted list of *.sql filenames found inside
 * `dir`.  Throws a descriptive error when the directory is missing or
 * cannot be read.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted SQL filenames (not full paths).
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.sql'))
    .map(entry => entry.name)
    .sort(); // lexicographic — relies on the numeric prefix convention

  return sqlFiles;
}

/**
 * Simulates running migrations by logging each filename that would be
 * applied, in order.  No database connection is made.
 *
 * @param {string}   dir      - Absolute path to the migrations directory.
 * @param {string[]} sqlFiles - Ordered list of SQL filenames to apply.
 */
function runMigrations(dir, sqlFiles) {
  if (sqlFiles.length === 0) {
    console.log('No migration files found — nothing to apply.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s) in: ${dir}\n`);
  console.log('Migrations to apply (in order):');
  console.log('─'.repeat(40));

  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(dir, filename);
    const stats    = fs.statSync(filePath);

    console.log(
      `  [${String(index + 1).padStart(2, '0')}] ${filename}` +
      `  (${stats.size} bytes)`
    );
  });

  console.log('─'.repeat(40));
  console.log(`\n${sqlFiles.length} migration(s) would be applied.`);
}

// ─── Entry point ──────────────────────────────────────────────────────────────

(function main() {
  try {
    const sqlFiles = getSqlFiles(MIGRATIONS_DIR);
    runMigrations(MIGRATIONS_DIR, sqlFiles);
  } catch (err) {
    console.error(`Migration error: ${err.message}`);
    process.exit(1);
  }
})();

