-- Migration 003: Add role column to users
ALTER TABLE users
  ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'user';

/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs the
 * filenames in the order they would be applied.
 *
 * Ordering rules (applied in priority order):
 *  1. Files whose names begin with a numeric prefix (e.g. 001_, 002_) are
 *     sorted numerically by that prefix so that 2_ always comes before 10_.
 *  2. Files without a numeric prefix are sorted alphabetically and placed
 *     after all numbered files.
 *
 * Usage:
 *   node migrate.js              # default migrations directory
 *   node migrate.js ./other/dir  # custom migrations directory
 */

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Directory that contains the *.sql migration files. */
const MIGRATIONS_DIR = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(__dirname, 'migrations');

/** Only files with this extension are treated as migrations. */
const SQL_EXTENSION = '.sql';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Extracts the leading integer prefix from a filename, if present.
 *
 * Examples:
 *   "001_create_users.sql" → 1
 *   "42-add-index.sql"     → 42
 *   "initial.sql"          → null
 *
 * @param {string} filename
 * @returns {number|null}
 */
function numericPrefix(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : null;
}

/**
 * Comparator that sorts migration filenames in application order:
 *  - Numbered files first, ordered by their numeric prefix (ascending).
 *  - Un-numbered files last, ordered alphabetically among themselves.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function migrationComparator(a, b) {
  const numA = numericPrefix(a);
  const numB = numericPrefix(b);

  // Both numbered → sort by number
  if (numA !== null && numB !== null) return numA - numB;

  // Only a is numbered → a comes first
  if (numA !== null) return -1;

  // Only b is numbered → b comes first
  if (numB !== null) return 1;

  // Neither numbered → alphabetical
  return a.localeCompare(b);
}

// ---------------------------------------------------------------------------
// Core logic
// ---------------------------------------------------------------------------

/**
 * Returns all *.sql filenames from `dir`, sorted in migration order.
 *
 * @param {string} dir  Absolute path to the migrations directory.
 * @returns {string[]}  Sorted array of bare filenames (not full paths).
 */
function getMigrationFiles(dir) {
  let entries;

  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Migrations directory not found: ${dir}`);
    }
    throw err;
  }

  return entries
    .filter(name => path.extname(name).toLowerCase() === SQL_EXTENSION)
    .sort(migrationComparator);
}

/**
 * Logs the migration plan to stdout — one filename per line.
 *
 * @param {string}   dir    Absolute path to the migrations directory.
 * @param {string[]} files  Sorted array of migration filenames.
 */
function logMigrationPlan(dir, files) {
  console.log('──────────────────────────────────────────');
  console.log('  Database Migration Plan');
  console.log('──────────────────────────────────────────');
  console.log(`  Directory : ${dir}`);
  console.log(`  Found     : ${files.length} migration(s)`);
  console.log('──────────────────────────────────────────');

  if (files.length === 0) {
    console.log('  (no migrations to apply)');
  } else {
    files.forEach((file, index) => {
      console.log(`  [${String(index + 1).padStart(3, '0')}] ${file}`);
    });
  }

  console.log('──────────────────────────────────────────');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

function main() {
  let files;

  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  logMigrationPlan(MIGRATIONS_DIR, files);
}

main();

