// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a .env file and returns a Map of key → raw-value pairs.
 *
 * Supported syntax:
 *   KEY=value          plain value
 *   KEY="value"        double-quoted value (quotes stripped)
 *   KEY='value'        single-quoted value (quotes stripped)
 *   # comment          ignored
 *   (blank lines)      ignored
 *
 * Only the first occurrence of a key is kept; later duplicates are ignored.
 * No variable interpolation is performed — values are returned verbatim.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Map<string, string>}
 */
function parseEnvFile(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Env file not found: ${filePath}`);
    }
    throw err;
  }

  const map = new Map();

  for (const line of raw.split('\n')) {
    // Strip trailing carriage-return (Windows line endings)
    const trimmed = line.replace(/\r$/, '').trim();

    // Skip blank lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue; // not a key=value line

    const key = trimmed.slice(0, eqIndex).trim();
    let   val = trimmed.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    // First occurrence wins
    if (key !== '' && !map.has(key)) {
      map.set(key, val);
    }
  }

  return map;
}

/**
 * Reads DATABASE_URL from the given env-variable map and returns a safe,
 * redacted summary object — never exposing the username or password.
 *
 * Returned shape:
 *   { protocol, host, port, database, redactedUrl }
 *
 * @param {Map<string, string>} envMap
 * @param {string}              envFilePath  Used only in error messages.
 * @returns {{ protocol: string, host: string, port: string,
 *             database: string, redactedUrl: string }}
 */
function resolveConnectionString(envMap, envFilePath) {
  if (!envMap.has('DATABASE_URL')) {
    throw new Error(`DATABASE_URL not found in ${envFilePath}`);
  }

  const rawUrl = envMap.get('DATABASE_URL');

  let parsed;
  try {
    parsed = new url.URL(rawUrl);
  } catch {
    throw new Error('DATABASE_URL is not a valid URL');
  }

  const protocol = parsed.protocol.replace(/:$/, '');         // "postgres"
  const host     = parsed.hostname;                            // "db.internal"
  const port     = parsed.port ||
                   (protocol === 'postgres' || protocol === 'postgresql'
                     ? '5432' : '');
  // pathname is "/<dbname>"; strip the leading slash
  const database = parsed.pathname.replace(/^\//, '') || '(default)';

  // Build a URL that is safe to log: omit user-info entirely
  const redactedUrl = `${protocol}://${host}:${port}/${database}`;

  return { protocol, host, port, database, redactedUrl };
}

/**
 * Logs the connection summary to stdout.
 * Credentials are never included in any log line.
 *
 * @param {string} envFilePath
 * @param {{ protocol: string, host: string, port: string,
 *           database: string, redactedUrl: string }} conn
 */
function logConnection(envFilePath, conn) {
  console.log('──────────────────────────────────────────');
  console.log('  Database Connection');
  console.log('──────────────────────────────────────────');
  console.log(`  Env file  : ${envFilePath}`);
  console.log(`  Protocol  : ${conn.protocol}`);
  console.log(`  Host      : ${conn.host}`);
  console.log(`  Port      : ${conn.port}`);
  console.log(`  Database  : ${conn.database}`);
  console.log(`  URL       : ${conn.redactedUrl}`);
  console.log('  Status    : connected successfully (simulated)');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

function main() {
  // -- Step 1: resolve connection string ------------------------------------
  let envMap;
  try {
    envMap = parseEnvFile(ENV_FILE);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  let conn;
  try {
    conn = resolveConnectionString(envMap, ENV_FILE);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  logConnection(ENV_FILE, conn);

  // -- Step 2: collect and log migration plan --------------------------------
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  logMigrationPlan(MIGRATIONS_DIR, files);
}

main();

