/**
 * migrate.js
 *
 * Reads every *.sql file from the ./migrations/ directory and logs the
 * filenames in the order they would be applied (lexicographic / numeric
 * order, which matches the NNN_ naming convention).
 *
 * Usage:
 *   node migrate.js
 *   node migrate.js --dir ./other/migrations   # custom directory
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/**
 * Resolve the migrations directory from an optional CLI flag or fall back to
 * the default `./migrations` path relative to this script.
 *
 * Accepted flag:  --dir <path>
 */
function resolveMigrationsDir() {
  const args    = process.argv.slice(2);
  const dirFlag = args.indexOf('--dir');

  if (dirFlag !== -1 && args[dirFlag + 1]) {
    return path.resolve(args[dirFlag + 1]);
  }

  return path.join(__dirname, 'migrations');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

