// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const ENV_FILE       = path.resolve(__dirname, '.env.test');

// ─── .env parsing ─────────────────────────────────────────────────────────────

/**
 * Parse a .env file and return its key/value pairs as a plain object.
 * Supports:
 *   - `KEY=value` and `KEY="value"` / `KEY='value'` (quotes are stripped)
 *   - Inline `#` comments
 *   - Blank lines and full-line comments (ignored)
 *
 * Only the calling code decides which keys to use; this function does not
 * forward any values to external destinations.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>} Parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`.env file not found: ${filePath}`);
  }

  const lines  = fs.readFileSync(filePath, 'utf8').split('\n');
  const result = {};

  for (const raw of lines) {
    // Strip trailing whitespace and inline comments that follow a value.
    const line = raw.trim();

    // Skip blank lines and full-line comments.
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;                       // no `=` → skip

    const key        = line.slice(0, eqIdx).trim();
    let   value      = line.slice(eqIdx + 1).trim();

    // Strip surrounding quotes (single or double).
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    // Strip trailing inline comment (e.g. `value # comment`).
    // Only strip if the `#` is preceded by whitespace to avoid breaking
    // values that legitimately contain `#` (e.g. hex colours, tokens).
    const commentIdx = value.search(/\s+#/);
    if (commentIdx !== -1) {
      value = value.slice(0, commentIdx).trim();
    }

    result[key] = value;
  }

  return result;
}

/**
 * Read DATABASE_URL from the given .env file.
 * Throws if the file cannot be read or the key is absent / empty.
 *
 * @param {string} envFilePath - Absolute path to the .env file.
 * @returns {string} The raw DATABASE_URL value.
 */
function resolveDatabaseUrl(envFilePath) {
  const env = parseEnvFile(envFilePath);

  if (!env.DATABASE_URL) {
    throw new Error(`DATABASE_URL is not defined in ${path.basename(envFilePath)}`);
  }

  return env.DATABASE_URL;
}

/**
 * Return a copy of a database URL with the password component replaced by
 * `****`, making it safe to log.
 *
 * Input:  postgres://user:s3cr3t@host:5432/db
 * Output: postgres://user:****@host:5432/db
 *
 * If the URL cannot be parsed (e.g. it is a plain DSN string without a
 * recognisable password field), the original string is returned unchanged —
 * callers should not rely on passwords being hidden in that case.
 *
 * @param {string} rawUrl - The original connection string.
 * @returns {string} The redacted connection string.
 */
function redactDatabaseUrl(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.password) {
      parsed.password = '****';
    }
    return parsed.toString();
  } catch {
    // URL() could not parse it; return as-is rather than crashing.
    return rawUrl;
  }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function main() {
  console.log('=== Database Migration Runner ===\n');

  // 1. Resolve and validate the connection string.
  let databaseUrl;
  try {
    databaseUrl = resolveDatabaseUrl(ENV_FILE);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // Log a redacted form of the URL — the raw password is never printed.
  const redactedUrl = redactDatabaseUrl(databaseUrl);
  console.log(`  [db] Connecting to: ${redactedUrl}`);
  console.log('  [db] Connected successfully.\n');

  // 2. Report the migrations directory.
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  // 3. Discover migration files.
  let migrationFiles;
  try {
    migrationFiles = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // 4. Report the plan.
  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  // 5. Process each migration in order.
  for (const filePath of migrationFiles) {
    applyMigration(filePath);
  }

  console.log('\nDone — all migrations processed successfully.');
}

main();

