/**
 * migrate.js
 *
 * Reads all .sql files from the ./migrations/ directory and logs each
 * filename it would apply, in lexicographic (numeric-prefix) order.
 *
 * Usage:
 *   node migrate.js
 *
 * To extend this script to actually execute migrations, replace the
 * "Dry-run" section below with real database calls (see comments).
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns an array of absolute paths to every .sql file inside `dir`,
 * sorted lexicographically so that numeric prefixes (001_, 002_, …)
 * define a deterministic application order.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted list of absolute .sql file paths.
 */
function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic sort — relies on numeric filename prefixes

  if (sqlFiles.length === 0) {
    throw new Error(`No ${SQL_EXTENSION} files found in: ${dir}`);
  }

  return sqlFiles;
}

/**
 * Reads and returns the SQL content of a single migration file.
 *
 * @param {string} dir      - Absolute path to the migrations directory.
 * @param {string} filename - Bare filename (e.g. "001_create_users.sql").
 * @returns {string} Raw SQL text.
 */
function readMigration(dir, filename) {
  const fullPath = path.join(dir, filename);
  return fs.readFileSync(fullPath, 'utf8');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

function runMigrations() {
  console.log('=== Database Migration Runner ===\n');
  console.log(`Migrations directory : ${MIGRATIONS_DIR}`);

  // 1. Discover migration files
  let files;
  try {
    files = getSqlFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  console.log(`Migrations found     : ${files.length}\n`);
  console.log('─'.repeat(40));

  // 2. Iterate in order and log each migration that would be applied
  let applied = 0;

  for (const filename of files) {
    applied += 1;

    // Read the SQL so we can surface the first comment line as a description
    const sql  = readMigration(MIGRATIONS_DIR, filename);
    const desc = extractDescription(sql);

    console.log(`[${String(applied).padStart(3, '0')}] Applying : ${filename}`);
    if (desc) {
      console.log(`       Description : ${desc}`);
    }

    /*
     * ── To execute for real, replace this block with your DB driver. ──────
     *
     * Example using the `pg` package:
     *
     *   const { Client } = require('pg');
     *   const client = new Client({ connectionString: process.env.DATABASE_URL });
     *   await client.connect();
     *   await client.query(sql);
     *   await client.end();
     *
     * ─────────────────────────────────────────────────────────────────────
     */
    console.log(`       Status      : (dry-run — no DB connection)\n`);
  }

  console.log('─'.repeat(40));
  console.log(`\n✔  ${applied} migration(s) would be applied (dry-run complete).`);
}

/**
 * Extracts the first non-empty SQL comment line from `sql` and returns it
 * as a plain description string, or `null` if none is found.
 *
 * Supports both single-line (--) and block (/* … *\/) comment styles.
 *
 * @param {string} sql
 * @returns {string|null}
 */
function extractDescription(sql) {
  for (const line of sql.split('\n')) {
    const trimmed = line.trim();

    // Single-line comment: -- Some description
    const singleMatch = trimmed.match(/^--+\s*(.+)/);
    if (singleMatch) return singleMatch[1].trim();

    // Block comment opener: /* Some description
    const blockMatch = trimmed.match(/^\/\*+\s*(.+)/);
    if (blockMatch) {
      // Strip a trailing */ if the comment opens and closes on one line
      return blockMatch[1].replace(/\*\/$/, '').trim();
    }
  }
  return null;
}

// ─── Entry point ──────────────────────────────────────────────────────────────

runMigrations();

