/**
 * migrate.js
 *
 * Database migration runner.
 *
 * Reads all *.sql files from the ./migrations/ directory, sorts them
 * lexicographically (so numeric prefixes like 001_, 002_ define the order),
 * and logs each filename it would apply.
 *
 * Usage:
 *   node migrate.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const url  = require('url');

// ─── Configuration ────────────────────────────────────────────────────────────

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');
const SQL_EXTENSION  = '.sql';
const ENV_FILE       = path.resolve(__dirname, '.env.test');

// ─── Env Parsing ──────────────────────────────────────────────────────────────

/**
 * Parses a .env-style file and returns its key/value pairs as a plain object.
 * Handles:
 *   - `KEY=value` lines
 *   - Inline `# comments`
 *   - Quoted values ("value" or 'value')
 *   - Blank lines and full-line comments (ignored)
 *
 * Only the file's contents are used — nothing is written to process.env so
 * that unrelated variables are never leaked into the running environment.
 *
 * @param {string} filePath - Absolute path to the env file.
 * @returns {Object.<string, string>} Parsed key/value map.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const vars = {};
  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and full-line comments
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    // Strip inline comments, then remove optional surrounding quotes
    let value = line.slice(eqIndex + 1).replace(/#.*$/, '').trim();
    if (/^["'].*["']$/.test(value)) {
      value = value.slice(1, -1);
    }

    vars[key] = value;
  }

  return vars;
}

/**
 * Reads DATABASE_URL from the env file and validates it is present.
 * Only DATABASE_URL is extracted — all other variables in the file are
 * intentionally ignored.
 *
 * @returns {string} The raw DATABASE_URL value.
 */
function resolveDatabaseUrl() {
  const vars = parseEnvFile(ENV_FILE);

  const dbUrl = vars['DATABASE_URL'];
  if (!dbUrl) {
    throw new Error(`DATABASE_URL is not defined in ${ENV_FILE}`);
  }

  return dbUrl;
}

/**
 * Returns a redacted, human-readable summary of a database URL so that
 * credentials (username and password) are never written to logs.
 *
 * Input : postgres://admin:s3cr3t@db.internal:5432/production
 * Output: postgres://[REDACTED]@db.internal:5432/production
 *
 * @param {string} rawUrl - The full database connection string.
 * @returns {string} A redacted version safe to log.
 */
function redactDatabaseUrl(rawUrl) {
  try {
    const parsed = new url.URL(rawUrl);
    // Replace username:password with a single [REDACTED] token
    parsed.username = '[REDACTED]';
    parsed.password = '';
    // URL encodes '[' and ']', so restore them for readability
    return parsed.toString().replace('%5BREDACTED%5D', '[REDACTED]');
  } catch {
    // If the URL can't be parsed, return a fully masked fallback
    return '[REDACTED — could not parse URL]';
  }
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Returns every *.sql file inside `dir`, sorted lexicographically.
 * Throws a descriptive error when the directory cannot be read.
 *
 * @param {string} dir - Absolute path to the migrations directory.
 * @returns {string[]} Sorted array of filenames (not full paths).
 */
function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  const sqlFiles = entries
    .filter(entry => entry.isFile() && entry.name.endsWith(SQL_EXTENSION))
    .map(entry => entry.name)
    .sort(); // lexicographic — numeric prefixes (001_, 002_, …) guarantee order

  return sqlFiles;
}

/**
 * Reads and returns the SQL content of a single migration file.
 *
 * @param {string} dir      - Absolute path to the migrations directory.
 * @param {string} filename - Name of the SQL file.
 * @returns {string} Raw SQL content.
 */
function readMigrationSQL(dir, filename) {
  const filePath = path.join(dir, filename);
  return fs.readFileSync(filePath, 'utf8');
}

// ─── Main ─────────────────────────────────────────────────────────────────────

/**
 * Entry point.
 * Resolves the DB connection string, discovers migration files, logs the plan,
 * then processes each one in order.
 */
function main() {
  console.log('=== Database Migration Runner ===\n');

  // 1. Resolve and simulate the database connection
  let dbUrl;
  try {
    dbUrl = resolveDatabaseUrl();
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  const redactedUrl = redactDatabaseUrl(dbUrl);
  console.log(`Env file        : ${ENV_FILE}`);
  console.log(`Connecting to   : ${redactedUrl}`);
  console.log(`Status          : Connected successfully (dry-run)\n`);
  console.log(`Migrations dir  : ${MIGRATIONS_DIR}\n`);

  // 2. Discover migration files
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found. Nothing to apply.');
    return;
  }

  // 3. Log the full plan before doing anything
  console.log(`Found ${files.length} migration(s) to apply:\n`);
  files.forEach((filename, index) => {
    console.log(`  [${String(index + 1).padStart(3, '0')}] ${filename}`);
  });
  console.log('');

  // 4. Process each file in order
  let applied = 0;

  for (const filename of files) {
    console.log(`----------------------------------------------------------`);
    console.log(`Applying migration: ${filename}`);

    try {
      const sql = readMigrationSQL(MIGRATIONS_DIR, filename);

      // ── Replace this block with a real DB call, e.g.: ──────────────────────
      //
      //   await client.query(sql);
      //
      // ── For now we simply log what would be executed: ──────────────────────
      console.log(`  Status : PENDING (dry-run — no DB connection configured)`);
      console.log(`  SQL    :\n`);

      // Indent each line of the SQL for readability
      sql.split('\n').forEach(line => console.log(`    ${line}`));

      applied++;
    } catch (err) {
      console.error(`  [ERROR] Failed to read ${filename}: ${err.message}`);
      console.error('Migration run aborted.');
      process.exit(1);
    }
  }

  console.log('----------------------------------------------------------');
  console.log(`\n=== Migration run complete: ${applied}/${files.length} file(s) processed ===`);
}

main();
